{
  "name": "llisa",
  "version": "1.1.0",
  "description": "Lisa - LLM-powered epic workflows for OpenCode",
  "type": "module",
  "main": "dist/index.js",
  "bin": {
    "llisa": "bin/cli.js"
  },
  "files": [
    "dist",
    "bin",
    "assets"
  ],
  "scripts": {
    "build": "bun build src/index.ts --outdir dist --target bun --format esm",
    "prepublishOnly": "npm run build"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "plugin",
    "epic",
    "workflow",
    "ai",
    "automation",
    "lisa",
    "ralph-wiggum"
  ],
  "author": "fractalswift",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/fractalswift/llisa.git"
  },
  "homepage": "https://github.com/fractalswift/llisa#readme",
  "bugs": {
    "url": "https://github.com/fractalswift/llisa/issues"
  },
  "engines": {
    "node": ">=18.0.0"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "^1.1.25",
    "typescript": "^5.0.0"
  }
}

#!/usr/bin/env node

import { existsSync, readFileSync, writeFileSync, unlinkSync, rmSync, copyFileSync, mkdirSync, statSync } from 'fs';
import { join, dirname } from 'path';
import { fileURLToPath } from 'url';
import { homedir } from 'os';

const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);

const PLUGIN_NAME = 'llisa';

const colors = {
  green: (s) => `\x1b[32m${s}\x1b[0m`,
  yellow: (s) => `\x1b[33m${s}\x1b[0m`,
  red: (s) => `\x1b[31m${s}\x1b[0m`,
  cyan: (s) => `\x1b[36m${s}\x1b[0m`,
  dim: (s) => `\x1b[2m${s}\x1b[0m`,
};

function printHelp() {
  console.log(`
${colors.cyan('Lisa - LLM-powered epic workflows')}

Usage:
  npx ${PLUGIN_NAME}

Run from a project directory to install Lisa globally and enable it for the current project.

Options:
  --help, -h    Show this help message

After installation, run ${colors.cyan('opencode')} and type ${colors.cyan('/lisa-help')} to get started!
`);
}

const SKILL_DIRS = [
  'lisa-create-epic',
  'lisa-continue',
  'lisa-yolo',
  'lisa-list-epics',
  'lisa-epic-status',
  'shared',
];

const COMMAND_FILES = [
  'lisa-create-epic.md',
  'lisa-list-epics.md',
  'lisa-epic-status.md',
  'lisa-continue.md',
  'lisa-yolo.md',
  'lisa-help.md',
];

function installSkillsTo(baseDir) {
  for (const skillDir of SKILL_DIRS) {
    const isShared = skillDir === 'shared';
    const fileName = isShared ? 'COMMON.md' : 'SKILL.md';
    const sourcePath = join(__dirname, '..', 'assets', 'skills', skillDir, fileName);

    if (!existsSync(sourcePath)) {
      throw new Error(`Source skill file not found: ${sourcePath}`);
    }

    const destDir = join(baseDir, skillDir);
    mkdirSync(destDir, { recursive: true });
    const destPath = join(destDir, fileName);
    copyFileSync(sourcePath, destPath);
    console.log(colors.green(`  ${destPath}`));
  }
}

function installCommandsTo(baseDir) {
  mkdirSync(baseDir, { recursive: true });
  for (const file of COMMAND_FILES) {
    const sourcePath = join(__dirname, '..', 'assets', 'commands', file);
    if (!existsSync(sourcePath)) {
      throw new Error(`Source command file not found: ${sourcePath}`);
    }
    const destPath = join(baseDir, file);
    copyFileSync(sourcePath, destPath);
    console.log(colors.green(`  ${destPath}`));
  }
}

function registerPlugin(configPath) {
  let config = {};

  if (existsSync(configPath)) {
    try {
      config = JSON.parse(readFileSync(configPath, 'utf-8'));
    } catch (e) {
      console.log(colors.red(`Error: ${configPath} exists but is not valid JSON.`));
      console.log(colors.dim(`  ${e.message}`));
      process.exit(1);
    }
  }

  if (!config.$schema) config.$schema = 'https://opencode.ai/config.json';
  if (!config.plugin) config.plugin = [];

  if (!config.plugin.includes(PLUGIN_NAME)) {
    config.plugin.push(PLUGIN_NAME);
    mkdirSync(dirname(configPath), { recursive: true });
    writeFileSync(configPath, JSON.stringify(config, null, 2) + '\n');
    console.log(colors.green(`  ${configPath}`));
  } else {
    console.log(colors.dim(`  ${configPath} (already registered)`));
  }
}

function cleanupOldInstalls(projectDir) {
  // Remove stale per-project copies from old installer versions
  const oldPaths = [
    join(projectDir, '.opencode', 'skill', 'lisa'),
    join(projectDir, '.opencode', 'command', 'lisa.md'),
    ...SKILL_DIRS.map(d => join(projectDir, '.opencode', 'skills', d)),
    ...COMMAND_FILES.map(f => join(projectDir, '.opencode', 'commands', f)),
  ];

  let cleaned = false;
  for (const p of oldPaths) {
    try {
      if (existsSync(p)) {
        const stat = statSync(p);
        if (stat.isDirectory()) {
          rmSync(p, { recursive: true, force: true });
        } else {
          unlinkSync(p);
        }
        console.log(colors.dim(`  Removed old per-project file: ${p}`));
        cleaned = true;
      }
    } catch {
      // ignore
    }
  }
  return cleaned;
}

async function install() {
  const home = homedir();
  const projectDir = process.cwd();

  console.log('');
  console.log(colors.cyan('Lisa - Intelligent Epic Workflow Plugin'));
  console.log('');

  // Clean up stale per-project installs from old versions
  const cleaned = cleanupOldInstalls(projectDir);
  if (cleaned) console.log('');

  // Install skills globally
  console.log('Installing skills...');
  installSkillsTo(join(home, '.config', 'opencode', 'skills'));
  installSkillsTo(join(home, '.claude', 'skills'));
  console.log('');

  // Install commands globally
  console.log('Installing commands...');
  installCommandsTo(join(home, '.config', 'opencode', 'commands'));
  installCommandsTo(join(home, '.claude', 'commands'));
  console.log('');

  // Register plugin in global OpenCode config
  console.log('Registering plugin...');
  registerPlugin(join(home, '.config', 'opencode', 'opencode.json'));
  console.log('');

  // Enable in current project
  console.log('Enabling in current project...');
  registerPlugin(join(projectDir, 'opencode.json'));
  console.log('');

  console.log(colors.green('Done!'));
  console.log('');
  console.log(`Run ${colors.cyan('opencode')} and type ${colors.cyan('/lisa-help')} to get started.`);
  console.log(`To enable Lisa in another project, run ${colors.cyan('npx llisa')} from that directory.`);
  console.log('');
}

async function main() {
  const args = process.argv.slice(2).filter(a => a !== '--opencode'); // backwards compat: ignore --opencode silently

  if (args.includes('--help') || args.includes('-h')) {
    printHelp();
    process.exit(0);
  }

  await install();
}

main().catch((err) => {
  console.error(colors.red('Error:'), err.message);
  process.exit(1);
});
